        return;
      }
      showConsole('developer');
    });
  }

  if (selectExtConsole) {
    selectExtConsole.addEventListener('click', () => {
      if (!currentUser) {
        authModal.classList.add('open');
        return;
      }
      showConsole('extension');
    });
  }

  // Back to Services (returns user to previous step)
  if (backToServicesBtn) {
    backToServicesBtn.addEventListener('click', () => {
      showServiceSelector();
    });
  }

  // Developer active key actions in sidebar
  if (switchKeyBtn) {
